MATCH (o:Owner)-[:Owns]->(t:Team)-[:LocatedIn]->(c:City)
WHERE o.nationality IS NOT NULL AND c.population IS NOT NULL
  AND EXISTS { MATCH (o)-[:MentionedIn]->(:Document) }
  AND EXISTS { MATCH (t)-[:MentionedIn]->(:Document) }
  AND EXISTS { MATCH (c)-[:MentionedIn]->(:Document) }
RETURN o.nationality AS col1, MIN(CAST(REPLACE(c.population, ',', '') AS INT64)) AS col2

